def cover_svg():
    def ball(x,y,r,c):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}" stroke="#1e293b"/>'
    def bond(x1,y1,x2,y2,w=4):return f'<path d="M{x1} {y1}L{x2} {y2}" stroke="#334155" stroke-width="{w}"/>'
    s=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 170" role="img" aria-label="Unit 16 cover molecules: ethane, ethene, ethyne and benzene ring (coded reconstruction)"><rect width="560" height="170" fill="#f8fafc"/>']
    s.append(bond(40,60,100,60)+''.join(bond(x,60,x+dx,60+dy,3) for x,dx,dy in ((40,-22,-24),(40,-22,24),(40,-28,0),(100,22,-24),(100,22,24),(100,28,0))))
    s.append(ball(40,60,11,'#1e3a8a')+ball(100,60,11,'#1e3a8a')+''.join(ball(x,y,6,'#b91c1c') for x,y in ((18,36),(18,84),(12,60),(122,36),(122,84),(128,60))))
    s.append(bond(170,40,230,40,3)+bond(170,48,230,48,3)+''.join(bond(x,44,x+dx,44+dy,3) for x,dx,dy in ((170,-20,-22),(170,-20,22),(230,20,-22),(230,20,22))))
    s.append(ball(170,44,11,'#1e3a8a')+ball(230,44,11,'#1e3a8a')+''.join(ball(x,y,6,'#b91c1c') for x,y in ((150,22),(150,66),(250,22),(250,66))))
    s.append(bond(160,120,250,120,3)+bond(185,114,225,114,3)+bond(185,126,225,126,3)+ball(185,120,10,'#1e3a8a')+ball(225,120,10,'#1e3a8a')+ball(160,120,6,'#b91c1c')+ball(250,120,6,'#b91c1c'))
    import math
    pts=[(400+46*math.cos(math.radians(a)),85+46*math.sin(math.radians(a))) for a in range(30,390,60)]
    s.append('<polygon points="'+' '.join(f'{x:.0f},{y:.0f}' for x,y in pts)+'" fill="none" stroke="#7c3aed" stroke-width="14" stroke-linejoin="round" opacity=".75"/>')
    for x,y in pts:
        hx,hy=400+(x-400)*1.55,85+(y-85)*1.55
        s.append(bond(x,y,hx,hy,2)+f'<circle cx="{hx:.0f}" cy="{hy:.0f}" r="9" fill="#bfdbfe" stroke="#1e3a8a"/><text x="{hx:.0f}" y="{hy+4:.0f}" text-anchor="middle" font-size="10" fill="#1e3a8a">H</text>')
    return ''.join(s)+'</svg>'
